import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { defineCollection } from 'astro:content';
import { z } from 'astro/zod';
import { docsLoader, i18nLoader } from '@astrojs/starlight/loaders';
import { docsSchema, i18nSchema } from '@astrojs/starlight/schema';
import { parseChangelog, versionAnchor } from './lib/changelog';

/**
 * docs: the Starlight documentation, generated by `npm run sync-docs` (do not edit by hand).
 *   src/content/docs/docs/**     English, served under /docs/
 *   src/content/docs/fr/docs/**  French, served under /fr/docs/
 *
 * releases: one entry per version of src/content/releases/CHANGELOG.md, the changelog of the
 * main repository copied by `npm run sync-docs` (do not edit it by hand). Rendered by
 * src/pages/releases/index.astro and its French twin.
 */
const CHANGELOG = 'src/content/releases/CHANGELOG.md';

const releases = defineCollection({
  loader: {
    name: 'changelog-loader',
    load: async ({ store, parseData, renderMarkdown, generateDigest, config, watcher, logger }) => {
      const path = fileURLToPath(new URL(CHANGELOG, config.root));
      const sync = async () => {
        const versions = parseChangelog(await readFile(path, 'utf8'));
        if (versions.length === 0) logger.warn(`${CHANGELOG}: no version found.`);
        store.clear();
        for (const [position, v] of versions.entries()) {
          const id = versionAnchor(v.version);
          const data = await parseData({ id, data: { ...v, body: undefined, position } });
          const rendered = await renderMarkdown(v.body);
          // Prefix the heading ids with the version: every version has its "Added" section.
          rendered.html = rendered.html.replace(/\bid="([^"]+)"/g, `id="${id}-$1"`);
          store.set({ id, data, body: v.body, rendered, digest: generateDigest(v.body + JSON.stringify(data)) });
        }
      };
      await sync();
      watcher?.add(path);
      watcher?.on('change', (changed) => {
        if (changed === path) void sync();
      });
    },
  },
  schema: z.object({
    version: z.string(),
    date: z.string().nullable(),
    unreleased: z.boolean(),
    yanked: z.boolean(),
    url: z.url().nullable(),
    /** Order in the changelog: 0 is the newest. */
    position: z.number(),
  }),
});

export const collections = {
  docs: defineCollection({ loader: docsLoader(), schema: docsSchema() }),
  /** Overrides of Starlight's interface strings: src/content/i18n/{en,fr}.json. */
  i18n: defineCollection({ loader: i18nLoader(), schema: i18nSchema() }),
  releases,
};
